package org.agentfrc.lesson;
import java.nio.file.*;import java.security.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
public class CoralContactTest {
 static Path out;static Properties input=new Properties(),results=new Properties();static byte[] raw;
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}static double d(String k){return Double.parseDouble(input.getProperty(k));}
 @BeforeAll static void hal()throws Exception{out=Path.of(Objects.requireNonNull(System.getenv("FRC_CORAL_OUTPUT"),"Fresh native-bound input required"));raw=Files.readAllBytes(out.resolve("input.properties"));input.load(new java.io.ByteArrayInputStream(raw));assertEquals("frc-coral-contact-input/v1",input.getProperty("schema"));assertEquals(input.getProperty("experimentSha256"),sha(Files.readAllBytes(out.resolve("experiment.json"))));for(String v:new String[]{"compressed","nominal"})assertEquals(input.getProperty(v+"PropertiesSha256"),sha(Files.readAllBytes(out.resolve(v+"/properties.json"))));assertTrue(d("floorMinXM")<=-.35-d("lengthM")/2,"Native floor contains entire supported tube footprint");assertTrue(d("floorMaxXM")>=.35+d("lengthM")/2,"Native floor contains entire supported tube footprint");edu.wpi.first.hal.HAL.initialize(500,0);}
 static CoralContactPlant.Config config(double mu,boolean nominal){return new CoralContactPlant.Config(d("massKg"),d("outerRadiusM"),d("innerRadiusM"),d("lengthM"),d("rollerRadiusM"),d(nominal?"nominalRollerInertiaKgM2":"rollerInertiaKgM2"),d(nominal?"nominalRollerZM":"rollerZM"),d("gear"),mu);}
 @AfterAll static void write()throws Exception{results.setProperty("inputSha256",sha(raw));for(Class<?> c:new Class<?>[]{CoralContactPlant.class,CoralAdvanceController.class,CoralContactRig.class})results.setProperty(c.getSimpleName()+"ClassSha256",sha(c.getResourceAsStream(c.getSimpleName()+".class").readAllBytes()));results.setProperty("capture","unestablished");results.setProperty("engineeringAcceptance","blocked");try(var w=Files.newBufferedWriter(out.resolve("result.properties"))){results.store(w,"Development evidence only");}}
 static double[] values(CoralContactPlant.Sample a){return new double[]{a.x(),a.z(),a.vx(),a.vz(),a.rollerOmega(),a.angle(),a.bus(),a.batteryAmps(),a.mechanicalResidual(),a.normalLoss(),a.frictionLoss()};}
 record Run(List<double[]> rows,String outcome){}
 static Run run(double mu,boolean nominal,int steps)throws Exception{String id=(nominal?"nominal":"compressed")+"-mu"+mu+"-steps"+steps;var rows=new ArrayList<double[]>();StringBuilder csv=new StringBuilder("t,x,z,vx,vz,omega,angle,bus,current,residual,normalLoss,frictionLoss,normalForce,constraintMoment,phase\n");String outcome="unobserved";try(var rig=new CoralContactRig(config(mu,nominal),1)){for(int i=0;i<170;i++){try{var a=rig.step(true,steps);rows.add(values(a));csv.append((i+1)*.02);for(double v:values(a))csv.append(',').append(v);csv.append(',').append(a.rollerNormal()).append(',').append(a.constraintMoment()).append(',').append(rig.controller.phase()).append('\n');assertTrue(Math.abs(a.mechanicalResidual())<2e-5,"Mechanical ledger residual");assertTrue(a.normalLoss()>=0&&a.frictionLoss()>=0);outcome=rig.controller.phase()==CoralAdvanceController.Phase.HOLD?"beam-triggered-stop-not-capture":rig.controller.phase()==CoralAdvanceController.Phase.FAULT?"controller-fault":"no-beam-stop";}catch(IllegalArgumentException e){assertTrue(e.getMessage().contains("Unsupported regeneration"),e.getMessage());outcome="unsupported-electrical: "+e.getMessage();break;}}}Files.writeString(out.resolve(id+".csv"),csv,StandardOpenOption.CREATE_NEW);results.setProperty(id+".outcome",outcome);return new Run(rows,outcome);}
 @Test void nativeBoundProfilesAndAlignedRefinement()throws Exception{double[] max=new double[11];for(boolean nominal:new boolean[]{false,true})for(double mu:new double[]{0,.2,.4,.8}){var a=run(mu,nominal,200);var b=run(mu,nominal,400);assertEquals(a.outcome().split(":")[0],b.outcome().split(":")[0],"Refined outcome category");assertEquals(a.rows.size(),b.rows.size(),"Same supported sampled horizon");for(int i=0;i<a.rows.size();i++)for(int j=0;j<11;j++)max[j]=Math.max(max[j],Math.abs(a.rows.get(i)[j]-b.rows.get(i)[j]));}double[] tol={1e-5,1e-5,1e-4,1e-4,1e-3,1e-4,1e-4,.005,2e-5,2e-5,2e-5};for(int j=0;j<11;j++){results.setProperty("refinementMax."+j,Double.toString(max[j]));assertTrue(max[j]<tol[j],"Refinement component "+j+" delta="+max[j]);}}
 @Test void independentFiniteEntryVector(){var p=CoralContactPlant.upper(config(.2,false),-.160,.05715,.15,0,-10);assertEquals(1.6625957357789525,p.normal(),1e-10);assertEquals(.6304420768835949,p.fx(),1e-10);assertEquals(-2.033684119794874,p.fz(),1e-10);assertEquals(.03378394534317356,p.rollerTorque(),1e-10);assertEquals(-.34273475101046186,p.constraintMoment(),1e-10);assertEquals(-.24327314189919635,p.fx()*.15+p.rollerTorque()*-10,1e-10);}
 @Test void finiteEndsAndNominalTangency(){for(double x:new double[]{-.25,.25})assertEquals(0,CoralContactPlant.upper(config(.2,false),x,.05715,.1,0,-10).normal());assertEquals(0,CoralContactPlant.upper(config(.2,true),0,.05715,0,0,0).normal(),1e-10);assertTrue(CoralContactPlant.upper(config(.2,false),0,.05715,0,0,0).normal()>0);}
 @Test void unsupportedBoreAndInvalidStates(){assertThrows(IllegalArgumentException.class,()->CoralContactPlant.upper(config(.2,false),0,.09,0,0,0));assertThrows(IllegalArgumentException.class,()->CoralContactPlant.upper(config(.2,false),Double.NaN,.05715,0,0,0));assertThrows(IllegalArgumentException.class,()->new CoralContactPlant(config(.2,false),0,.04,0));}
 @Test void disabledFaultLatches(){try(var rig=new CoralContactRig(config(.2,false),1)){rig.step(false,200);assertEquals(CoralAdvanceController.Phase.FAULT,rig.controller.phase());rig.step(true,200);assertEquals(CoralAdvanceController.Phase.FAULT,rig.controller.phase());}}
 @Test void wrongEncoderSignFaults(){try(var rig=new CoralContactRig(config(.2,false),-1)){for(int i=0;i<5;i++)rig.step(true,200);assertEquals(CoralAdvanceController.Phase.FAULT,rig.controller.phase());}}
 @Test void blockedBeamFaultsAtInitialization(){try(var rig=new CoralContactRig(config(.2,false),1,1)){rig.step(true,200);assertEquals(CoralAdvanceController.Phase.FAULT,rig.controller.phase());}}
 @Test void missingBeamNeverCompletes(){try(var controller=new CoralAdvanceController()){var encoder=edu.wpi.first.wpilibj.simulation.EncoderSim.createForChannel(0);var beam=new edu.wpi.first.wpilibj.simulation.DIOSim(2);var pwm=new edu.wpi.first.wpilibj.simulation.PWMSim(0);edu.wpi.first.wpilibj.simulation.RoboRioSim.setVInVoltage(12);beam.setValue(true);for(int i=0;i<151;i++){encoder.setCount(-i);controller.periodic(true);}assertEquals(CoralAdvanceController.Phase.FAULT,controller.phase());assertEquals(0,pwm.getSpeed());beam.setValue(false);controller.periodic(true);assertEquals(CoralAdvanceController.Phase.FAULT,controller.phase());assertEquals(0,pwm.getSpeed());}try(var rig=new CoralContactRig(config(.2,false),1,2)){try{for(int i=0;i<170;i++)rig.step(true,200);}catch(IllegalArgumentException e){assertTrue(e.getMessage().contains("Unsupported regeneration"));}assertNotEquals(CoralAdvanceController.Phase.HOLD,rig.controller.phase());}}
 @Test void beamStopIsLatchedAndDisableOverrides(){try(var rig=new CoralContactRig(config(.2,false),1)){for(int i=0;i<170;i++)rig.step(true,200);assertEquals(CoralAdvanceController.Phase.HOLD,rig.controller.phase());rig.step(false,200);assertEquals(CoralAdvanceController.Phase.FAULT,rig.controller.phase());}}
}


